import SwiftUI

/// Menu "Check for updates" (mac plugin only: the App Store updates the
/// iPad app). Fetches `<vendor site>/releases.json` — generated by the
/// oxo-music.com Rails app from its config/releases.yml, the same file as
/// the product page's download buttons — and compares this build with the
/// latest one for its platform by BUILD NUMBER only (always increasing,
/// never reset; "1.4" vs "1.31" is left to humans), the version is only
/// shown. No entry for the product / platform = up to date. `OXO_UPDATE_PRODUCT`
/// (Identity.xcconfig) = the product's slug there; empty = no menu entry
/// (forks, and the builds without the generated identity header).
enum UpdateCheck {
    static let product = OXO_UPDATE_PRODUCT
    static var enabled: Bool { !product.isEmpty }
    static let platform = "mac"
    static let site = OXO_VENDOR_URL
    static var siteName: String { URL(string: site)?.host ?? site }
    static var email: String { OXO_VENDOR_EMAIL.replacingOccurrences(of: "mailto:", with: "") }
    static var releasesURL: URL? { URL(string: site + "/releases.json") }

    /// This build: the bundle holding this code (the .vst3, also when the
    /// AUv2 wrapper loads it).
    static let installed: (version: String, build: Int) = {
        final class Probe {}
        let info = Bundle(for: Probe.self).infoDictionary
        return (info?["CFBundleShortVersionString"] as? String ?? "1.0",
                Int(info?["CFBundleVersion"] as? String ?? "") ?? 0)
    }()

    enum State: Equatable {
        case checking
        case latest(installed: String)
        case available(latest: String, installed: String, page: URL)
        case unavailable
    }

    /// Calls `done` on the main queue.
    static func run(url: URL? = releasesURL, done: @escaping (State) -> Void) {
        guard let url else { return done(.unavailable) }
        var request = URLRequest(url: url, cachePolicy: .reloadIgnoringLocalCacheData, timeoutInterval: 15)
        request.setValue("application/json", forHTTPHeaderField: "Accept")
        URLSession(configuration: .ephemeral).dataTask(with: request) { data, response, _ in
            let ok = (response as? HTTPURLResponse)?.statusCode == 200
            let state = ok ? data.flatMap { evaluate($0, installed.version, installed.build) } : nil
            DispatchQueue.main.async { done(state ?? .unavailable) }
        }.resume()
    }

    /// nil = not our JSON (e.g. an HTML error page).
    static func evaluate(_ data: Data, _ version: String, _ build: Int) -> State? {
        guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let products = root["products"] as? [String: Any] else { return nil }
        let entry = products[product] as? [String: Any]
        guard let release = entry?[platform] as? [String: Any],
              let latestVersion = release["version"] as? String,
              let latestBuild = release["build"] as? Int, latestBuild > build
        else { return .latest(installed: "V" + version) }
        let page = (entry?["page"] as? String).flatMap(URL.init(string:))
            ?? URL(string: site + "/products/" + product)!
        return .available(latest: label(latestVersion, latestBuild, against: version),
                          installed: label(version, build, against: latestVersion), page: page)
    }

    /// "V1.31", plus the build when the other side has the same version.
    private static func label(_ version: String, _ build: Int, against other: String) -> String {
        "V" + version + (version == other ? " (build \(build))" : "")
    }

    static func message(_ state: State) -> String {
        switch state {
        case .checking:
            return "Checking \(siteName)…"
        case .latest(let installed):
            return "You're using the latest version (\(installed))."
        case let .available(latest, installed, page):
            return "A new version \(latest) is available on \(page.absoluteString)\n\nYour version is \(installed)."
        case .unavailable:
            return "\(siteName) is not available. Please try again later, or contact \(email) if the problem persists."
        }
    }
}

/// The answer, drawn inside the panel like the Themes dialog (the host owns
/// the window). A click outside, OK or Esc closes it.
struct UpdateDialog: View {
    @ObservedObject var model: SynthModel
    let state: UpdateCheck.State
    @Environment(\.openURL) private var openURL

    var body: some View {
        ZStack {
            Color.black.opacity(0.3).contentShape(Rectangle()).onTapGesture { model.update = nil }
            VStack(spacing: 0) {
                Text("Check for updates").font(.system(size: 11, weight: .semibold)).foregroundColor(Dlg.text)
                    .frame(maxWidth: .infinity).frame(height: 22).background(Dlg.bar)
                VStack(alignment: .leading, spacing: 14) {
                    Text(text).font(.system(size: 11)).foregroundColor(Dlg.text)
                        .tint(Dlg.accent)
                        .fixedSize(horizontal: false, vertical: true)
                        .textSelection(.enabled)
                    HStack(spacing: 8) {
                        Spacer()
                        if case .available(_, _, let page) = state {
                            button("Download page") {
                                model.update = nil
                                openURL(page)
                            }
                        }
                        button(state == .checking ? "Cancel" : "OK") { model.update = nil }
                    }
                }
                .padding(14)
            }
            .frame(width: 360)
            .background(RoundedRectangle(cornerRadius: 8).fill(Dlg.bg))
            .overlay(RoundedRectangle(cornerRadius: 8).strokeBorder(Color.black.opacity(0.7), lineWidth: 1))
            .clipShape(RoundedRectangle(cornerRadius: 8))
            .shadow(color: .black.opacity(0.5), radius: 10, y: 4)
            #if os(macOS)
            .background(WheelShield())
            #endif
        }
    }

    /// The message, its page URL clickable.
    private var text: AttributedString {
        var s = AttributedString(UpdateCheck.message(state))
        if case .available(_, _, let page) = state, let r = s.range(of: page.absoluteString) {
            s[r].link = page
            s[r].underlineStyle = .single
        }
        return s
    }

    private func button(_ title: String, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Text(title).font(.system(size: 11)).foregroundColor(Dlg.text)
                .padding(.horizontal, 12).frame(minWidth: 64).frame(height: 22)
                .background(RoundedRectangle(cornerRadius: 3).fill(Dlg.bar))
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
    }
}
